<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {request} from '../api/client'
import {Refresh,CopyDocument,Search,ArrowRight} from '@element-plus/icons-vue'
import {ElMessage} from 'element-plus'
const source=ref('postgres'),tables=ref<Array<{name:string;estimatedRows:number}>>([]),table=ref(''),page=ref(1),total=ref(0),rows=ref<Array<Record<string,unknown>>>([]),busy=ref(false),error=ref(''),pattern=ref('*'),cursor=ref('0'),nextCursor=ref('0'),keyDetail=ref<Record<string,unknown>|null>(null),dialog=ref(false),simple=ref(false),filter=ref(''),copyOpen=ref(false),copyContent=ref(''),cursorHistory=ref<string[]>([])
const visible=computed(()=>rows.value.filter(row=>JSON.stringify(row).toLowerCase().includes(filter.value.toLowerCase())))
let epoch=0,controller:AbortController|undefined
async function load(){const version=++epoch;controller?.abort();controller=new AbortController();busy.value=true;error.value='';rows.value=[];try{if(source.value==='postgres'){if(!tables.value.length)tables.value=await request('/data/postgres/tables',{signal:controller.signal});if(version!==epoch)return;if(!table.value)table.value=tables.value[0]?.name??'';if(table.value){const out=await request<{items:typeof rows.value;total:number}>(`/data/postgres/tables/${encodeURIComponent(table.value)}?page=${page.value}&pageSize=25`,{signal:controller.signal});if(version!==epoch)return;rows.value=out.items;total.value=out.total}}else{const out=await request<{items:typeof rows.value;cursor:string;total:number}>(`/data/redis/keys?cursor=${cursor.value}&pattern=${encodeURIComponent(pattern.value)}`,{signal:controller.signal});if(version!==epoch)return;rows.value=out.items;nextCursor.value=out.cursor;total.value=out.total}}catch(e){if(version!==epoch||e instanceof DOMException&&e.name==='AbortError')return;error.value=e instanceof Error?e.message:'数据读取失败'}finally{if(version===epoch)busy.value=false}}
function change(){page.value=1;cursor.value='0';cursorHistory.value=[];filter.value='';void load()}
async function detail(row:Record<string,unknown>){try{keyDetail.value=source.value==='redis'?await request(`/data/redis/value?key=${encodeURIComponent(String(row.key))}`):row;dialog.value=true}catch(e){error.value=e instanceof Error?e.message:'详情不可用'}}
function next(){cursorHistory.value.push(cursor.value);cursor.value=nextCursor.value;void load()}
function previous(){cursor.value=cursorHistory.value.pop()??'0';void load()}
async function copy(){const text=visible.value.map(row=>JSON.stringify(row)).join('\n');try{if(!navigator.clipboard)throw new Error();await navigator.clipboard.writeText(text);ElMessage.success('当前页原始数据已复制')}catch{copyContent.value=text;copyOpen.value=true}}
onMounted(load);onUnmounted(()=>{++epoch;controller?.abort()})
</script>
<template>
<section class="data-workspace"><header class="console-toolbar"><div><h1>数据库浏览</h1><p>只读 · 原始数据控制台</p></div><div class="console-actions"><div class="mode-toggle"><el-switch id="data-simple" v-model="simple" aria-label="简约模式"/><label for="data-simple">简约模式</label></div><el-button :icon="Refresh" :loading="busy" @click="load">刷新数据</el-button><el-button :icon="CopyDocument" :disabled="!visible.length||busy" @click="copy">复制当前页</el-button></div></header>
<div class="data-controls"><div><label>数据库来源</label><el-radio-group v-model="source" aria-label="数据库来源" @change="change"><el-radio-button value="postgres">PostgreSQL</el-radio-button><el-radio-button value="redis">Redis</el-radio-button></el-radio-group></div><div v-if="source==='postgres'"><label>数据表</label><el-select v-model="table" aria-label="PostgreSQL数据表" filterable @change="change"><el-option v-for="t in tables" :key="t.name" :label="t.name" :value="t.name"/></el-select></div><div v-else><label>Redis键模式</label><el-input v-model="pattern" aria-label="Redis键筛选" placeholder="* 或 media-tool:*" @keyup.enter="change"/></div><div><label>筛选当前页</label><el-input v-model="filter" :prefix-icon="Search" aria-label="筛选当前页数据" clearable placeholder="只筛选此页已返回的原始内容"/></div><el-button v-if="source==='redis'" @click="change">筛选键</el-button></div>
<el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
<div class="data-note">按管理员要求显示原始字段值（包括密码哈希、密文及完整URL）。仅管理员可读，没有SQL或删除入口，请勿公开分享。</div>
<div class="data-console" tabindex="0" aria-label="数据库内容" :aria-busy="busy"><p v-if="busy" class="console-state">正在读取数据…</p><p v-else-if="error" class="console-state">读取失败，请刷新重试。</p><p v-else-if="!visible.length" class="console-state">当前页没有符合条件的数据</p><button v-for="(row,index) in visible" :key="index" class="data-row" @click="detail(row)"><span class="data-row-id">{{source==='redis'?String(row.key):String((page-1)*25+index+1).padStart(3,'0')}}</span><code>{{JSON.stringify(simple?source==='redis'?{key:row.key,type:row.type,ttlSeconds:row.ttlSeconds}:Object.fromEntries(Object.entries(row).slice(0,4)):row)}}</code><ArrowRight aria-hidden="true"/></button></div>
<footer class="data-footer"><span v-if="source==='postgres'">{{table||'尚无数据表'}} · 共 {{total}} 行 · 每页25行 · 实时更新可能改变页序</span><span v-else>当前游标返回 {{rows.length}} 个键；数据库共 {{total}} 个键（非筛选匹配总数）。SCAN可返回空页或重复键。</span><el-pagination v-if="source==='postgres'" v-model:current-page="page" :page-size="25" :total="total" layout="prev,pager,next" :disabled="busy" @current-change="load"/><div v-else><el-button :disabled="!cursorHistory.length||busy" @click="previous">上一游标页</el-button><el-button :disabled="nextCursor==='0'||busy" @click="next">下一游标页</el-button></div></footer>
</section>
<el-dialog v-model="dialog" title="只读格式化数据" width="min(900px,95vw)"><pre class="data-detail">{{JSON.stringify(keyDetail,null,2)}}</pre><template #footer><el-button @click="dialog=false">关闭</el-button></template></el-dialog>
<el-dialog v-model="copyOpen" title="复制脱敏数据" width="min(740px,94vw)"><p class="field-hint">浏览器不能直接写入剪贴板，请选中文本复制；仅包含当前页脱敏记录。</p><el-input v-model="copyContent" type="textarea" readonly :rows="12" aria-label="待复制数据"/><template #footer><el-button @click="copyOpen=false">关闭</el-button></template></el-dialog>
</template>
<style scoped>
.data-workspace{background:var(--panel-bg);border:1px solid var(--border);border-radius:12px;overflow:hidden;min-width:0}.console-toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:20px}.console-toolbar h1{font-size:20px}.console-toolbar p{font-size:12px;color:var(--muted);margin-top:4px}.console-actions,.mode-toggle{display:flex;align-items:center;gap:10px}.mode-toggle{font-size:13px}.console-actions .el-button+.el-button{margin-left:0}.data-controls{display:grid;grid-template-columns:auto minmax(180px,1fr) minmax(180px,1fr);gap:16px;padding:4px 20px 18px;align-items:end}.data-controls label{display:block;font-size:12px;color:var(--muted);margin-bottom:6px}.data-controls .el-select{width:100%}.data-note{padding:0 20px 12px;font-size:12px;color:var(--muted)}.data-console{height:clamp(340px,calc(100dvh - 410px),800px);overflow:auto;overscroll-behavior:contain;background:#151b23;color:#e5e9f0;--focus:#8fc6ff}.data-row{display:grid;grid-template-columns:minmax(40px,auto) minmax(0,1fr) 20px;align-items:start;gap:16px;width:100%;padding:10px 12px;text-align:left;background:none;color:inherit;border-bottom:1px solid #2b3541;min-height:44px}.data-row:hover{background:#1d2631}.data-row-id{font:12px/1.8 monospace;color:#65acff;max-width:260px;overflow-wrap:anywhere}.data-row code{font-size:12px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}.data-row svg{color:#92a7be;width:12px}.console-state{padding:36px 20px;text-align:center;color:#b9c8d8}.data-footer{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:14px 20px;color:var(--muted);font-size:12px}.data-footer .el-pagination{margin:0}.data-detail{max-height:65dvh;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;padding:16px;background:#151b23;color:#e5e9f0;border-radius:8px}@media(max-width:1100px){.console-toolbar,.data-footer{flex-wrap:wrap}.data-controls{grid-template-columns:1fr 1fr}}@media(max-width:680px){.console-toolbar{padding:16px}.console-actions{flex-wrap:wrap;width:100%}.data-controls{padding:4px 16px 16px;grid-template-columns:1fr}.data-console{height:450px}.data-row{grid-template-columns:minmax(0,1fr) 20px;gap:6px}.data-row code{grid-column:1/-1;grid-row:2}.data-row-id{max-width:none}.data-footer{padding:14px 16px;overflow:auto}}
</style>
